import { useState } from 'react'
import { Copy, Share2 } from 'lucide-react'
import MockBadge from './MockBadge.jsx'

function buildSummary(report) {
  return [
    `🧠 Brain Rot Score: ${report.brainRotScore}/100`,
    '',
    report.roast,
    '',
    'Top red flags:',
    ...report.redFlags.map((flag) => `🚩 ${flag.title}: ${flag.description}`),
    '',
    'Generated by RoastTube — entertainment only, not a scientific assessment.',
  ].join('\n')
}

export default function ShareReport({ report, illustrative = false }) {
  const [copied, setCopied] = useState(false)

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(buildSummary(report))
      setCopied(true)
      window.setTimeout(() => setCopied(false), 2000)
    } catch {
      setCopied(false)
    }
  }

  return (
    <section className="rounded-2xl border border-line bg-white p-6 shadow-sm">
      <div className="flex items-start justify-between gap-3">
        <h3 className="flex items-center gap-2 text-sm font-semibold text-ink">
          <Share2 className="size-4 text-accent-500" aria-hidden="true" />
          Share this report
        </h3>
        <MockBadge show={illustrative} />
      </div>
      <p className="mt-2 text-xs text-muted">
        Copy a shareable summary to the clipboard. Reports you generate while
        signed in can be saved and revisited from your dashboard.
      </p>
      <button
        type="button"
        onClick={handleCopy}
        className="mt-4 inline-flex items-center gap-2 rounded-full bg-accent-500 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-accent-600 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-500"
      >
        <Copy className="size-4" aria-hidden="true" />
        {copied ? 'Copied!' : 'Copy shareable summary'}
      </button>
    </section>
  )
}
